        private FlowLayoutPanel Flow(){return new FlowLayoutPanel{Dock=DockStyle.Fill,WrapContents=false,AutoScroll=true,Margin=Padding.Empty,Padding=new Padding(0,4,0,0)};}
        private void AddLabel(FlowLayoutPanel panel,string text){panel.Controls.Add(new Label{Text=text,AutoSize=true,Margin=new Padding(2,6,7,3)});}
        private void AddRibbon(RibbonGroup group,string text,Action action,string name,string icon,string help,float weight=100){var b=new RibbonButton(icon){Name=name,Text=text};b.Click+=delegate{Guard(action);};group.AddCommand(b,weight);Help(b,help);}
        private void Help(Control control,string text){tips.SetToolTip(control,text);if(control is RibbonButton&&control.Parent!=null)tips.SetToolTip(control.Parent,text);}
        private void UndoHelp(){Help(undoDelete,undoDelete.Enabled?"Khôi phục dòng vừa xóa khỏi bảng, gồm nhãn, mô tả, màu và vị trí.\nChưa thay đổi Layer trong DWG.":"Chưa có dòng vừa xóa để khôi phục.\nNút này sẽ sáng khi anh xóa một dòng trong bảng.");}
        private void SetupGrid(DataGridView grid)
        {
            grid.Dock=DockStyle.Fill;grid.AutoGenerateColumns=false;grid.AllowUserToAddRows=false;grid.AllowUserToDeleteRows=false;grid.RowHeadersVisible=false;grid.SelectionMode=DataGridViewSelectionMode.CellSelect;grid.EditMode=DataGridViewEditMode.EditOnEnter;UiStyle.Grid(grid);grid.BackgroundColor=Color.White;grid.EnableHeadersVisualStyles=false;grid.ColumnHeadersDefaultCellStyle.BackColor=Color.FromArgb(229,237,244);grid.AlternatingRowsDefaultCellStyle.BackColor=Color.FromArgb(247,249,252);grid.DataSource=binding;
            grid.CurrentCellDirtyStateChanged+=delegate{if(grid.IsCurrentCellDirty&&(grid.CurrentCell is DataGridViewCheckBoxCell||grid.CurrentCell is DataGridViewComboBoxCell))grid.CommitEdit(DataGridViewDataErrorContexts.Commit);};grid.CellValueChanged+=delegate{Dirty();};grid.CellEndEdit+=delegate{RefreshNames();UpdateCurrent();RefreshDirection();Dirty();};grid.DataError+=delegate(object sender,DataGridViewDataErrorEventArgs e){e.ThrowException=false;e.Cancel=true;report.Text="Giá trị trong bảng chưa hợp lệ. Sửa lại trước khi tiếp tục.";};
        }
        private void Column(DataGridView grid,string property,string title,int width,int minimum,bool readOnly=false)
        {DataGridViewColumn c=property=="Enabled"?(DataGridViewColumn)new DataGridViewCheckBoxColumn():new DataGridViewTextBoxColumn();c.Name=property;c.DataPropertyName=property;c.HeaderText=title;c.Width=width;c.FillWeight=width;c.MinimumWidth=minimum;c.ReadOnly=readOnly;c.SortMode=DataGridViewColumnSortMode.NotSortable;grid.Columns.Add(c);}
        private void ActionColumn(string name,string text,int width){list.Columns.Add(new DataGridViewButtonColumn{Name=name,HeaderText="",Text=text,UseColumnTextForButtonValue=true,FillWeight=width,MinimumWidth=60,ReadOnly=true});}
        private void PlaceHeaderCheck(){if(list.Columns.Count==0)return;var r=list.GetCellDisplayRectangle(0,-1,true);useAll.Bounds=new Rectangle(r.Left+2,r.Top+3,Math.Max(70,r.Width-4),Math.Max(24,r.Height-6));useAll.BringToFront();}
        private void RefreshChecks(){if(rows==null)return;int count=rows.Count(r=>r.Enabled);useAll.CheckState=count==0?CheckState.Unchecked:count==rows.Count?CheckState.Checked:CheckState.Indeterminate;useAll.Enabled=rows.Count>0;useAll.Visible=rows.Count>0;PlaceHeaderCheck();}
        private void ApplyAppearance(){apply.BackColor=apply.Enabled?Color.FromArgb(24,99,148):Color.FromArgb(224,228,232);apply.ForeColor=apply.Enabled?Color.White:Color.DimGray;apply.Invalidate();Help(apply,apply.Enabled?"Tạo theo kế hoạch vừa kiểm tra: chỉ thêm tên chưa có; giữ nguyên Layer, Linetype và style đang dùng.\nKiểm tra hiển thị rồi lưu DWG.":rows!=null&&!rows.Any(r=>r.Enabled)?"Đang khóa vì chưa tích dòng Dùng.\nTích Dùng hoặc Dùng tất cả, rồi bấm 1. Kiểm tra thay đổi.":"Đang khóa: cần Kiểm tra thay đổi đạt với cấu hình hiện tại.\nBấm 1. Kiểm tra thay đổi; nếu đã sửa cấu hình thì kiểm tra lại.");}
        private void UpdateCurrent(){var r=binding.Current as GasRow;currentInfo.Text=r==null?"Danh sách trống. Nhấn + Tạo hệ mới để bắt đầu.":"Đang xem: "+r.SystemCode+" · "+r.Text+"   | Sửa / Xóa ở cuối dòng; bấm ô màu để đổi một dòng hoặc cả hệ.";}
        private void Dirty(){if(loading)return;apply.Enabled=false;RefreshChecks();ApplyAppearance();summary.Text=rows==null?"":rows.Count(r=>r.Enabled)+" / "+rows.Count+" dòng Dùng • "+(rows.Any(r=>r.Enabled)?"Cần Kiểm tra thay đổi trước khi áp dụng vào DWG.":"Tích Dùng ít nhất một dòng để kiểm tra / áp dụng.");}
        private void RefreshNames(){if(loading||profile==null||rows==null)return;loading=true;try{profile.Rows=rows.ToList();profile.LayerPrefix=layerPrefix.Text.Trim();profile.UnitTag=unitTag.Text.Trim().ToUpperInvariant();profile.RefreshNames();list.Invalidate();parameters.Invalidate();}finally{loading=false;}}
        private void RefreshDirection(){if(rows==null)return;bool prior=loading;loading=true;try{direction.SelectedIndex=rows.Count==0?(newRotation=="R"?1:0):rows.Count>0&&rows.All(r=>r.RotationMode=="U"&&r.RotationDegrees==0)?0:rows.Count>0&&rows.All(r=>r.RotationMode=="R"&&r.RotationDegrees==0)?1:2;}finally{loading=prior;}}
        private void SetProfile(Profile p){loading=true;profile=p;rows=new BindingList<GasRow>(p.Rows);binding.DataSource=rows;rows.ListChanged+=delegate{Dirty();};units.SelectedIndex=3;factor.Value=(decimal)p.GeometryFactor;padding.Value=(decimal)p.PaddingRatio;unitTag.Text=p.UnitTag;font.Text=p.FontFile;bold.Checked=p.FontBold;layerPrefix.Text=p.LayerPrefix;automatic.Checked=p.AutoFitOnSync;p.RefreshNames();binding.ResetBindings(false);deletedRow=null;undoDelete.Enabled=false;loading=false;scanned="";RefreshDirection();UpdateCurrent();Dirty();}
        private void EndEdits(){if(!list.EndEdit()||!parameters.EndEdit())throw new InvalidDataException("Sửa giá trị không hợp lệ trong bảng trước.");binding.EndEdit();}
        private Profile Read(bool requireSelected=true){EndEdits();profile.Rows=rows.ToList();profile.UnitTag=unitTag.Text.Trim().ToUpperInvariant();profile.LayerPrefix=layerPrefix.Text.Trim();profile.GeometryFactor=(double)factor.Value;profile.PaddingRatio=(double)padding.Value;profile.FontFile=font.Text.Trim();profile.FontBold=bold.Checked;profile.AutoFitOnSync=automatic.Checked;profile.RefreshNames();if(requireSelected&&!profile.Selected.Any())throw new InvalidDataException("Chưa có dòng nào tích Dùng. Tích ô Dùng ở từng dòng hoặc Dùng tất cả ở đầu bảng, rồi bấm Kiểm tra thay đổi.");profile.RequireValid(requireSelected);return profile;}
        private string Fingerprint(Profile p){return Profile.Hash(p.LayerPrefix+"|"+p.UnitTag+"|"+p.FontBold+"|"+p.AutoFitOnSync+"|"+Profile.N(p.PaddingRatio)+"|"+String.Join(";",p.Selected.Select(r=>p.LayerNameFor(r)+":"+p.Signature(r)+":"+r.ColorIndex+":"+r.DescriptionText)));}
        private void Scan(){apply.Enabled=false;var p=Read();report.Text=inspect==null?"Chưa kết nối AutoCAD.":inspect(p);binding.ResetBindings(false);scanned=Fingerprint(p);apply.Enabled=inspect!=null&&synchronize!=null&&!report.Text.Contains("Xung đột");summary.Text=apply.Enabled?"Kiểm tra đạt • Sẵn sàng áp dụng "+p.Selected.Count+" dòng vào DWG.":"Chưa thể áp dụng. Xem báo cáo kiểm tra phía trên.";}
        private void Sync(){string checkedHash=scanned;var p=Read();if(checkedHash!=Fingerprint(p))throw new InvalidDataException("Cấu hình đã đổi. Bấm Kiểm tra thay đổi trước khi áp dụng.");report.Text=synchronize==null?"Chưa kết nối AutoCAD.":synchronize(p);scanned="";apply.Enabled=false;summary.Text="Đã tạo các tên mới; tên đã tồn tại được giữ nguyên. Kiểm tra hiển thị rồi lưu DWG.";}
        private void Guard(Action action){try{action();}catch(InvalidDataException ex){apply.Enabled=false;report.Text=ex.Message;summary.Text="Chưa thực hiện thao tác. "+ex.Message;}catch(Exception ex){apply.Enabled=false;report.Text="Bước: "+ex.Data["MrT.Stage"]+Environment.NewLine+ex;if(ErrorHandler!=null)ErrorHandler(ex);else MessageBox.Show(this,ex.Message,"Layer + Linetype",MessageBoxButtons.OK,MessageBoxIcon.Information);}}
        private void OpenProfile(){using(var d=new OpenFileDialog{Filter="Cấu hình JSON|*.json"})if(d.ShowDialog(DialogOwner)==DialogResult.OK)SetProfile(Profile.Load(d.FileName));}
        private void SaveProfile(){var p=Read(false);using(var d=new SaveFileDialog{Filter="Cấu hình JSON|*.json",FileName="my-layer-linetype.json"})if(d.ShowDialog(DialogOwner)==DialogResult.OK){p.Save(d.FileName);summary.Text="Đã lưu cấu hình: "+d.FileName;}}
        private void ImportLin(){using(var d=new FolderBrowserDialog{Description="Thư mục LIN tham khảo (chỉ đọc)"})if(d.ShowDialog(DialogOwner)==DialogResult.OK)SetProfile(LinReader.ReadFolder(d.SelectedPath));}
        private void ExportLin(){var p=Read();if(p.AutoFitOnSync&&fit!=null){fit(p);binding.ResetBindings(false);Dirty();}using(var d=new SaveFileDialog{Filter="Linetype LIN|*.lin",FileName="MrT-Linetypes.lin"})if(d.ShowDialog(DialogOwner)==DialogResult.OK){File.WriteAllText(d.FileName,p.ExportLin(),Encoding.ASCII);report.Text="Đã xuất LIN. Khi LOAD thủ công cần style "+p.StyleName+", font "+p.FontFile+", cao 0, rộng 1.";}}
        private void Fit(){var p=Read();if(fit==null)throw new InvalidDataException("Mở add-in trong AutoCAD để đo font.");report.Text=fit(p);binding.ResetBindings(false);Dirty();}
        public void PrepareEmbedded()
        {
            TopLevel=false;FormBorderStyle=FormBorderStyle.None;MinimumSize=Size.Empty;Dock=DockStyle.Fill;newRotation="R";var root=(TableLayoutPanel)Controls[0];root.ColumnStyles.Clear();root.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,100));foreach(int row in new[]{0,1,7}){root.RowStyles[row].Height=0;var control=root.GetControlFromPosition(0,row);if(control!=null)control.Visible=false;}RefreshDirection();
        }
        public void MainAction(string command)
        {
            Guard(delegate{switch(command){case "New":AddSystem();break;case "Inspect":Scan();break;case "Create":if(!apply.Enabled)throw new InvalidDataException("Kiểm tra cấu hình trước khi tạo.");Sync();break;case "Samples":if(samples!=null)samples(Read());break;case "Open":OpenProfile();break;case "Save":SaveProfile();break;case "Import":ImportLin();break;case "Export":ExportLin();break;case "Color":ChangeColor();break;case "Fit":Fit();break;case "Undo":UndoDelete();break;}});
        }
        public Profile SnapshotDraft(){EndEdits();return new Profile{SchemaVersion=profile.SchemaVersion,UnitTag=unitTag.Text.Trim(),LayerPrefix=layerPrefix.Text.Trim(),GeometryFactor=(double)factor.Value,PaddingRatio=(double)padding.Value,FontFile=font.Text.Trim(),FontBold=bold.Checked,AutoFitOnSync=automatic.Checked,Rows=rows.Select(r=>r.Copy()).ToList()};}
        private void AddSystem(){var p=Read(false);var seed=new GasRow{Enabled=true,SystemCode="",LabelPrefix="",Diameter=110,Dash=10,GapBefore=8,GapAfter=8,TextScale=2.5,OffsetX=-7,OffsetY=-1,RotationMode=direction.SelectedIndex==0?"U":direction.SelectedIndex==1?"R":newRotation,RotationDegrees=0,ColorIndex=7};using(var d=new NewSystemForm(p,rows.ToList(),seed,colorPicker)){if(d.ShowDialog(DialogOwner)!=DialogResult.OK)return;foreach(var r in d.NewRows)rows.Add(r);RefreshNames();binding.Position=rows.Count-1;RefreshDirection();UpdateCurrent();Dirty();summary.Text="Đã thêm "+d.NewRows.Count+" dòng vào bảng. Chưa ghi DWG; Kiểm tra → Áp dụng để sử dụng.";}}
        private void EditRow(GasRow row){using(var d=new RowEditorForm(row,false,r=>rows.Any(x=>!Object.ReferenceEquals(x,row)&&(String.Equals(profile.NameFor(x),profile.NameFor(r),StringComparison.OrdinalIgnoreCase)||String.Equals(profile.LayerNameFor(x),profile.LayerNameFor(r),StringComparison.OrdinalIgnoreCase)))?"Tên Layer hoặc Linetype đã có trong bảng.":null,colorPicker)){if(d.ShowDialog(DialogOwner)!=DialogResult.OK)return;int index=rows.IndexOf(row);rows[index]=d.Value;RefreshNames();binding.Position=index;RefreshDirection();UpdateCurrent();Dirty();}}
        private void DeleteRow(GasRow row){deletedIndex=rows.IndexOf(row);deletedRow=row;rows.Remove(row);undoDelete.Enabled=true;RefreshNames();UpdateCurrent();Dirty();summary.Text="Đã bỏ "+row.Text+" khỏi bảng. Có thể Hoàn tác xóa dòng; thao tác này không xóa Layer khỏi DWG.";}
        private void UndoDelete(){if(deletedRow==null)return;if(rows.Any(r=>String.Equals(profile.NameFor(r),profile.NameFor(deletedRow),StringComparison.OrdinalIgnoreCase)||String.Equals(profile.LayerNameFor(r),profile.LayerNameFor(deletedRow),StringComparison.OrdinalIgnoreCase)))throw new InvalidDataException("Không khôi phục được vì tên Layer hoặc Linetype đã được tạo lại.");rows.Insert(Math.Min(deletedIndex,rows.Count),deletedRow);deletedRow=null;undoDelete.Enabled=false;RefreshNames();UpdateCurrent();Dirty();}
        private void ChangeColor(){Read(false);using(var d=new ColorGroupForm(rows.ToList(),binding.Current as GasRow,colorPicker)){if(d.ShowDialog(DialogOwner)!=DialogResult.OK)return;foreach(var row in d.Targets)row.ColorIndex=d.SelectedColor;binding.ResetBindings(false);Dirty();summary.Text="Đã đổi màu "+d.Targets.Count+" dòng trong bảng. Chỉ áp dụng khi tạo tên mới; sửa hiện hành ở màn hình DWG.";}}
        protected override void Dispose(bool disposing){if(disposing)tips.Dispose();base.Dispose(disposing);}
    }
}
